export const router = Router();

router.post("/check-alerts", async (req: Request, res: Response) => {
  const { warehouseId } = req.body;

  // Check for missed heartbeats
  const latestReading = getLatestReadingByWarehouse(Number(warehouseId));
  if (!latestReading || Date.now() - latestReading.timestamp > 60000) {
    res.status(200).json({ alert: "Missed heartbeat detected." });
    return;
  }

  // Check for out-of-range readings
  const devices = getDevicesByWarehouseId(Number(warehouseId));
  for (const device of devices) {
    const reading = getLatestReadingByWarehouse(device.id);
    if (reading && (reading.value < device.minValue || reading.value > device.maxValue)) {
      res.status(200).json({ alert: `Out-of-range reading detected for device ${device.id}.` });
      return;
    }
  }

  res.status(200).json({ message: "No alerts detected." });
});

