    const bookingEndDate = new Date(booking.endDate);
    const requestedStartDate = new Date(startDate as string);
    const requestedEndDate = new Date(endDate as string);
    return !(requestedStartDate < bookingEndDate && requestedEndDate > bookingStartDate);
  });

  res.json({ isAvailable });
});

