import { Router, type Request, type Response } from "express";
import { getStockLevelBySku, updateStockLevel } from "../db/stock-levels-table";
import { logStockMovement } from "../db/stock-movements-table";

export const router = Router();

router.post("/movement", (req: Request, res: Response) => {
  const { sku, quantity, movementType }: { sku: string, quantity: number, movementType: 'in' | 'out' } = req.body;

  // Log the stock movement
  logStockMovement(Number(sku), quantity, movementType);

  // Update the stock level
  const stockLevel = getStockLevelBySku(sku);
  if (!stockLevel) {
    res.status(404).send(`Stock level not found for SKU: ${sku}`);
    return;
  }

  let newCurrentQuantity = stockLevel.currentQuantity;
  if (movementType === 'in') {
    newCurrentQuantity += quantity;
  } else if (movementType === 'out') {
    newCurrentQuantity -= quantity;
  }

  updateStockLevel(sku, stockLevel.locationId, newCurrentQuantity, stockLevel.reorderThreshold);

  res.send({ message: `Stock movement logged and processed for SKU: ${sku}` });
});

